{
  "title": "雨夜验收",
  "synopsis": "暴雨中两人合力抢救备用线盒，排除二次故障。雨停后周野流露对老街的不舍，林岚承诺明早验收。面对周野的患得患失，林岚留下修到通电为止的坚定承诺。",
  "preview_blurb": "暴雨倾盆，刚包扎好的线路面临致命威胁。当老街的记忆与现实的阻碍交织，那句未敲响的铃声，还能否在雨停后如约而至？",
  "scenes": [
    {
      "title": "雨中抢救",
      "location": "广播站外墙与室内",
      "dramatic_goal": "抢救备用线盒并确认内部干燥，排除二次故障风险。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "卡扣！帮我按住右边，别让水灌进去！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "我拿身体挡着呢，你快盖！这雨太邪门了！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "锁死了。拿防水布，赶紧撤！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "呼……差点白干。我这身算是洗了个冷水澡。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "先别说话。让我测一下线盒。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "你测，你测。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "阻值正常，内部干燥，没有短路。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "谢天谢地。刚才冲出去那一下，真以为全完了。"
        },
        {
          "kind": "narration",
          "text": "雨水顺着两人的衣角滴落，在老旧的地板上砸出微弱的回响。"
        }
      ]
    },
    {
      "title": "雨停之后",
      "location": "广播站室内",
      "dramatic_goal": "安抚周野的情绪，确立次日验收目标，保留三声铃伏笔。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "你说，要是老街真拆了，街坊们都搬走，这广播站留着还有什么用？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "先擦擦头发吧，别着凉。明天上午我带仪器，来做最后的通电验收。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "验收……要是过了呢？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "过了就能正常播音，大家都能听见。"
        },
        {
          "kind": "narration",
          "text": "窗外的暴雨渐渐停歇，周野拿起一块干布，仔细擦拭着那只旧铜铃。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "擦干净了。明天验收完，就能敲这三声铃了吧？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "只要通电正常，就能敲。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "好，我等着你的好消息。"
        }
      ]
    },
    {
      "title": "门前的拉扯",
      "location": "广播站门口",
      "dramatic_goal": "面对周野的患得患失，林岚给出坚定承诺，留下情感悬念。",
      "lines": [
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "林岚！"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "还有事？早点休息吧。"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "host",
          "text": "如果……明天验收还是通不过，该怎么办？"
        },
        {
          "kind": "dialogue",
          "speaker_role_id": "repairer",
          "text": "那就修到通为止。"
        },
        {
          "kind": "narration",
          "text": "门被轻轻关上，把未尽的话语和那只安静的铜铃，一起留在了雨后的黑夜里。"
        }
      ]
    }
